const idle={phase:'LOADING',rows:[],error:null};

function ReadState({state,loadingTitle,emptyTitle,emptyBody,children}){
  if(state.phase==='LOADING')return <StateBlock tone="loading" title={loadingTitle}>Reading immutable, entity-scoped evidence from the accounting API.</StateBlock>;
  if(state.phase==='BLOCKED')return <StateBlock tone="blocked" title={state.error?.code||'AI_EVIDENCE_READ_BLOCKED'}>{state.error?.message} No substitute, browser-stored, or demonstration evidence is shown.</StateBlock>;
  if(state.rows.length===0)return <StateBlock tone="empty" title={emptyTitle}>{emptyBody}</StateBlock>;
  return children;
}

